using System;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using LastRail.Auth;
using LastRail.Battle;
using LastRail.Run;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class BBoardingEventsTests {
  internal static JObject Supplier()=>JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/combat-b-boarding-events-traces-20261004.json"));
  internal static JObject Packet()=>(JObject)Supplier()["traces"].First()["body"].DeepClone();
  internal static JObject Sample(int index)=>(JObject)Supplier()["syntheticSourceSamples"][index].DeepClone();
  [Test] public void NewDefinitionReaderUsesReceivedPolicyAndPreservesOriginalV1(){var type=typeof(BScoutGunnerDefinitionSnapshot).Assembly.GetType("LastRail.Run.BBoardingEventsDefinitionSnapshot");Assert.NotNull(type,"Missing actual v2 policy definition reader");var p=Packet();var value=BWaveBoardingRuntimeTests.Invoke(type,"Read",p,(string)p["packetHash"]);Assert.IsTrue(JToken.DeepEquals(p,(JObject)RunRiskBindingTests.Call(value,"Capture")));}
  [Test] public void NativeFactoryBindsReceivedV2SourceWithoutResettingOriginalHp(){var source=Source();var binding=BWaveBoardingRuntimeTests.WaveBinding(source.OriginalSource);var method=typeof(BDirectAttackBasicLoop).GetMethod("CreateBoardingEventsRuntime");Assert.NotNull(method,"Missing received v2 policy native composition");var native=(BDirectAttackBasicLoop)method.Invoke(null,new object[]{binding,source,null,10000});Assert.AreEqual(source.SourceHash,(string)native.Capture()["boardingEventsSourceHash"]);Assert.AreEqual(source.OriginalSourceHash,(string)native.Capture()["waveSourceHash"]);foreach(var actor in source.OriginalSource.Waves.SelectMany(w=>w.Instances))Assert.AreEqual((int)actor.Hp,native.Hp(actor.InstanceId));Assert.IsFalse(native.OrdinaryRuntimeGeometrySupported);}
  internal static JObject Trust(int index){var original=(JObject)Supplier()["originalSources"][index];return new JObject{["origin"]=original["origin"].DeepClone(),["nativeContextId"]=original["nativeContextId"].DeepClone(),["seedHash"]=original["seedHash"].DeepClone(),["sourceHash"]=original["sourceHash"].DeepClone(),["nodeId"]=original["nodeId"].DeepClone(),["visitDepth"]=original["visitDepth"].DeepClone(),["priorSourceHash"]=original["priorSourceHash"].DeepClone()};}
  internal static BBoardingEventsNodeSnapshot Source(int index=0){var p=Sample(index);return BBoardingEventsNodeSnapshot.Read(p,(string)p["sourceHash"],Trust(index));}
  [TestCase(0)][TestCase(1)][TestCase(2)] public void WrapperRetainsOriginalSourceAndIndependentContext(int index){var p=Sample(index);var source=Source(index);Assert.IsTrue(JToken.DeepEquals(p,source.Capture()));Assert.IsTrue(JToken.DeepEquals(p["originalSource"],source.OriginalSource.Capture()));Assert.IsTrue(JToken.DeepEquals(Supplier()["originalSources"][index],source.OriginalSource.Capture()));Assert.IsFalse(source.CanStart);}
  [Test] public void ActualReceivedPolicyHasDurationsAndNullInterceptionSource(){var p=BBoardingEventsDefinitionSnapshot.Read(Packet(),BBoardingEventsDefinitionSnapshot.ApprovedPacketHash);Assert.AreEqual(600,p.Boarding.GraceMilliseconds);Assert.AreEqual(800,p.Boarding.ApproachMilliseconds);Assert.AreEqual(200,p.Boarding.AttachedMilliseconds);Assert.AreEqual(1800,p.Boarding.ClimbingMilliseconds);Assert.AreEqual(1,p.Boarding.LeftSockets);Assert.AreEqual(1,p.Boarding.RightSockets);Assert.IsFalse(p.InterceptionTimingSupported);Assert.IsNull(p.InterceptionPreparationMicroseconds);Assert.IsNull(p.InterceptionRecoveryMicroseconds);Assert.IsNull(p.InterceptionTimingSource);Assert.IsFalse(p.Events.NewReservationAtContactAllowed);Assert.IsTrue(p.Events.AutoOffPreservesInterception);CollectionAssert.AreEqual(new[]{"MANUAL_SKILL","EMERGENCY_INTERCEPTION","AUTO_SKILL","BASIC_ATTACK"},p.Events.ActionPriority);Assert.IsTrue(JToken.DeepEquals(Packet()["definition"]["originalDefinition"],BScoutGunnerSourceTests.Packet()["definition"]));}
  [TestCase("GRACE",false,false,false)][TestCase("APPROACH",true,false,false)][TestCase("ATTACHED",true,false,true)][TestCase("CLIMBING",true,false,true)][TestCase("ROOFTOP",true,true,false)]
  public void PhaseEligibilityUsesOnlyAlreadyOwnedPhase(string phase,bool target,bool attack,bool climb){var p=Source().Definition.Boarding.Eligibility(phase);Assert.AreEqual(target,p.Targetable);Assert.AreEqual(attack,p.AttackEligible);Assert.AreEqual(climb,p.ClimbBonusEligible);}
  [TestCase("version")][TestCase("hash")][TestCase("definition")][TestCase("extra")][TestCase("capacity")]
  public void DefinitionRejectsWrongVersionHashPolicyAndCapacity(string fault){var p=Packet();string hash=BBoardingEventsDefinitionSnapshot.ApprovedPacketHash;if(fault=="version")p["version"]=BScoutGunnerDefinitionSnapshot.Version;if(fault=="hash")hash=new string('f',64);if(fault=="definition")p["definition"]["interceptionTiming"]["preparationUs"]=0;if(fault=="extra")p["private"]=true;if(fault=="capacity")p["payload"]=new string('z',524289);Assert.Throws<ArgumentException>(()=>BBoardingEventsDefinitionSnapshot.Read(p,hash));}
  [TestCase("version")][TestCase("wrapperHash")][TestCase("originalHash")][TestCase("context")][TestCase("seed")][TestCase("policy")][TestCase("capacity")]
  public void SourceRejectsWrongOriginalTrustAndWrapper(string fault){var p=Sample(0);var trust=Trust(0);string hash=(string)p["sourceHash"];if(fault=="version")p["version"]=BScoutGunnerDefinitionSnapshot.Version;if(fault=="wrapperHash")hash=new string('f',64);if(fault=="originalHash")trust["sourceHash"]=new string('f',64);if(fault=="context")trust["nativeContextId"]="foreign";if(fault=="seed")trust["seedHash"]=new string('f',64);if(fault=="policy")p["definition"]["boarding"]["hitRestartsClimb"]=true;if(fault=="capacity")p["payload"]=new string('z',524289);Assert.Throws<ArgumentException>(()=>BBoardingEventsNodeSnapshot.Read(p,hash,trust));}
  static RunApiHttpResponse Response(JObject p)=>RunApiHttpResponse.Success(200,p.ToString(),new[]{new RunApiHttpHeader("Cache-Control","no-store"),new RunApiHttpHeader("ETag",(string)p["packetHash"])});
  [Test] public async Task NewClientUsesExactVersionBearerAndRetainsPriorSnapshotOnFailure(){var p=Packet();var auth=RunRiskBindingTests.Session();var wire=new RunRiskBindingTests.Wire{Reply=r=>Task.FromResult(Response(p))};using var c=new BBoardingEventsDefinitionClient(new GameApiAuthenticatedHttpTransport(wire),()=>auth,()=>1);await c.RefreshAsync(BBoardingEventsDefinitionSnapshot.ApprovedPacketHash);Assert.NotNull(c.Snapshot);Assert.AreEqual("/v2/combat/b-scout-gunner-definition",wire.Last.EndpointPath);Assert.IsNull(wire.Last.BodyJson);Assert.IsTrue(wire.Last.Headers.Any(h=>h.Name=="Authorization"&&h.Value=="Bearer lst1.fixture"));Assert.IsTrue(wire.Last.Headers.Any(h=>h.Name=="X-Combat-B-Scout-Gunner-Version"&&h.Value==BBoardingEventsDefinitionSnapshot.Version));var original=c.Snapshot;wire.Reply=r=>Task.FromResult(RunApiHttpResponse.Success(409,"{\"errorCode\":\"combat_b_boarding_stale\"}"));await c.RefreshAsync(BBoardingEventsDefinitionSnapshot.ApprovedPacketHash);Assert.AreEqual("STALE",c.Status);Assert.AreSame(original,c.Snapshot);}
  [Test] public async Task RestoreCancelsPendingBorrowedWaitAndLateErrorCannotReplaceSnapshot(){var auth=RunRiskBindingTests.Session();var pending=new TaskCompletionSource<RunApiHttpResponse>();var wire=new RunRiskBindingTests.Wire{Reply=r=>pending.Task};using var c=new BBoardingEventsDefinitionClient(new GameApiAuthenticatedHttpTransport(wire),()=>auth,()=>1);var wait=c.RefreshAsync(BBoardingEventsDefinitionSnapshot.ApprovedPacketHash);c.RestoreVerified(Packet(),BBoardingEventsDefinitionSnapshot.ApprovedPacketHash);Assert.AreSame(wait,await Task.WhenAny(wait,Task.Delay(200)));await wait;pending.SetException(new InvalidOperationException("late"));Assert.NotNull(c.Snapshot);Assert.AreEqual("READY",c.Status);c.Dispose();Assert.IsNull(c.Snapshot);}
  [Test] public async Task AccountReplacementCannotPublishOldRequestAndOwnedCancellationEndsWait(){var auth=RunRiskBindingTests.Session();long generation=1;var pending=new TaskCompletionSource<RunApiHttpResponse>();var wire=new RunRiskBindingTests.Wire{Reply=r=>pending.Task};using var c=new BBoardingEventsDefinitionClient(new GameApiAuthenticatedHttpTransport(wire),()=>auth,()=>generation);var wait=c.RefreshAsync(BBoardingEventsDefinitionSnapshot.ApprovedPacketHash);auth=RunRiskBindingTests.Session();generation++;pending.SetResult(Response(Packet()));await wait;Assert.IsNull(c.Snapshot);pending=new TaskCompletionSource<RunApiHttpResponse>();using var stop=new CancellationTokenSource();wait=c.RefreshAsync(BBoardingEventsDefinitionSnapshot.ApprovedPacketHash,null,stop.Token);stop.Cancel();Assert.AreSame(wait,await Task.WhenAny(wait,Task.Delay(200)));await wait;Assert.AreEqual("CANCELLED",c.Status);pending.SetResult(Response(Packet()));Assert.IsNull(c.Snapshot);}
  [Test] public void ReceivedNativeStagesUseHalfOpenEligibilityAndPreserveOriginalCooldown(){var source=Source();var original=source.OriginalSource;var b=BWaveBoardingRuntimeTests.WaveBinding(original);var paths=BWaveBoardingRuntimeTests.Paths(b.Composition.Attack);var s=BDirectAttackBasicLoop.CreateBoardingEventsRuntime(b,source,paths,10000);JToken Life()=>s.Capture()["boarding"]["lives"][0];void Step(string id,int ms)=>s.Advance(id,ms*10000L,ms);Step("before",599);Assert.IsFalse((bool)Life()["targetable"]);Step("boundary",1);Assert.IsTrue((bool)Life()["targetable"]);Assert.IsFalse((bool)Life()["attackEligible"]);Step("attach",800);Assert.AreEqual("Attached",(string)Life()["phase"]);Step("climb",200);Assert.AreEqual("Climbing",(string)Life()["phase"]);Step("before-roof",1799);Assert.AreEqual("Climbing",(string)Life()["phase"]);var cache=s.Capture();var restored=BDirectAttackBasicLoop.RestoreBoardingEventsRuntime(cache,BDirectAttackInput.Digest(cache),b,source,paths,10000);Step("roof",1);restored.Advance("roof",10000,1);Assert.AreEqual("Rooftop",(string)Life()["phase"]);Assert.IsTrue((bool)Life()["attackEligible"]);Assert.IsFalse(source.Definition.Boarding.Eligibility("ROOFTOP").ClimbBonusEligible);Assert.IsTrue(JToken.DeepEquals(s.Capture(),restored.Capture()));long firstDue=(long)s.Capture()["state"]["direct"]["next"][original.Waves[0].Instances[0].InstanceId];Assert.GreaterOrEqual(firstDue,5000);Assert.AreEqual(BBoardingEventsDefinitionSnapshot.ApprovedDefinitionHash,(string)s.Capture()["receivedDefinitionHash"]);Assert.IsTrue(JToken.DeepEquals(source.Capture(),s.Capture()["boardingEventsSource"]));}
  [Test] public void WrongReceivedCacheAndOriginalBindingCannotReplaceNativeState(){var source=Source();var b=BWaveBoardingRuntimeTests.WaveBinding(source.OriginalSource);var s=BDirectAttackBasicLoop.CreateBoardingEventsRuntime(b,source,null,10000);var cache=s.Capture();cache["boardingEventsSourceHash"]=new string('f',64);Assert.Throws<ArgumentException>(()=>BDirectAttackBasicLoop.RestoreBoardingEventsRuntime(cache,BDirectAttackInput.Digest(cache),b,source,null,10000));Assert.Throws<ArgumentException>(()=>BDirectAttackBasicLoop.CreateBoardingEventsRuntime(BWaveBoardingRuntimeTests.WaveBinding(Source(1).OriginalSource),source,null,10000));Assert.AreEqual(source.SourceHash,(string)s.Capture()["boardingEventsSourceHash"]);}
  [Test] public void ReceivedPolicyUsesExistingNativeClimbDamageOnlyAtImpactPhase(){var source=Source();var original=source.OriginalSource;var b=BWaveBoardingRuntimeTests.ManualOperators(BWaveBoardingRuntimeTests.WaveBinding(original,BWaveBoardingRuntimeTests.HitPacket(original,true,false),null,"BCB04"));var s=BDirectAttackBasicLoop.CreateBoardingEventsRuntime(b,source,BWaveBoardingRuntimeTests.Paths(b.Composition.Attack),10000);void Step(string id,int ms)=>s.Advance(id,ms*10000L,ms);var first=original.Waves[0].Instances[0];Step("approach",1399);var approach=s.ApplyWaveBasic("approach-hit","op_mira",first.InstanceId,1).Hits.Single();Step("climb",1800);var climb=s.ApplyWaveBasic("climb-hit","op_mira",first.InstanceId,1).Hits.Single();Assert.Greater((long)climb.BuffSource["damageBps"],(long)approach.BuffSource["damageBps"]);Step("roof",2201);var roof=s.ApplyWaveBasic("roof-hit","op_mira",original.Waves[0].Instances[1].InstanceId,1).Hits.Single();Assert.AreEqual((long)approach.BuffSource["damageBps"],(long)roof.BuffSource["damageBps"]);Assert.AreEqual(source.SourceHash,(string)s.Capture()["boardingEventsSourceHash"]);}
  [Test] public void ReceivedSourceAndNativeStateStayUnchangedAfterPartialImpactCapacityFailure(){var source=Source();var original=source.OriginalSource;var p=BWaveBoardingRuntimeTests.HitPacket(original,true,false);p["stepTimeSpanTicks"]=100000;var profile=BWaveBoardingRuntimeTests.LocalBoundaryAttackProfile(p);var b=BWaveBoardingRuntimeTests.WaveBinding(original,p,profile);var s=BDirectAttackBasicLoop.CreateBoardingEventsRuntime(b,source,BWaveBoardingRuntimeTests.Paths(b.Composition.Attack),60);var before=s.Capture();Assert.Catch(()=>s.Advance("overflow",1000000000,10000));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));Assert.IsTrue(JToken.DeepEquals(source.Capture(),s.Capture()["boardingEventsSource"]));}
 }
}
